def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Gather basic statistics
    my_c = 0
    opp_c = 0
    for (me, opp) in history:
        if me == 'C':
            my_c += 1
        if opp == 'C':
            opp_c += 1

    opp_def = n - opp_c
    my_def = n - my_c
    last_me, last_opp = history[-1]

    # Opening: cooperate to allow mutual cooperation to form
    if n < 4:
        return 'C'

    # Recent window statistics
    w = 10 if n >= 10 else n
    recent = history[-w:]
    rec_opp_c = sum(1 for (a, b) in recent if b == 'C')
    rec_my_c = sum(1 for (a, b) in recent if a == 'C')

    opp_rate = opp_c / n
    rec_opp_rate = rec_opp_c / w

    # Opponent's trailing cooperation / defection streaks
    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break
    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break
    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    # Detect opponent whose behavior is highly cooperative: preserve mutual cooperation
    if opp_def <= max(1, n // 20) or (n >= 12 and rec_opp_rate >= 0.9):
        # Avoid endless mutual defection; only rare probing is safe
        # Near very end, don't suddenly defect against a strong cooperator unless it's a clear gain
        return 'C'

    # Opponent mostly defect-heavy: defect, but occasionally offer a cooperation probe
    if opp_rate < 0.2 and rec_opp_rate < 0.25:
        # If stuck in long mutual defection, offer a conciliatory single cooperation
        if opp_d_streak >= 2 and my_d_streak >= 2:
            # Deterministic periodic olive branch to allow recovery
            if (n % 5) == 0:
                return 'C'
        # Rare random probe
        if n > 15 and rng.random() < 0.08:
            return 'C'
        return 'D'

    # Strong recent defection streak: punish, but allow a quick repair
    if opp_d_streak >= 3:
        # If both stuck defecting, try a conciliatory action to break out
        if my_d_streak >= 2:
            return 'C' if rng.random() < 0.35 else 'D'
        return 'D'

    # If opponent just defected on us while we cooperated: retaliate once,
    # but be ready to forgive and return to cooperation quickly.
    if last_opp == 'D' and last_me == 'C':
        return 'D'

    # If opponent cooperated last round: reciprocate cooperation.
    if last_opp == 'C':
        # If we've been punishing for a while, return to cooperation now.
        if my_d_streak >= 1:
            return 'C'
        # Otherwise cooperate (maintain mutual cooperation)
        return 'C'

    # Fallback: if opponent defected and we also defected, attempt repair
    # when the overall history is not overwhelmingly defection-heavy.
    if last_opp == 'D' and last_me == 'D':
        if opp_rate > 0.35:
            # Forgiveness to escape DD loops
            return 'C' if rng.random() < 0.5 else 'D'
        return 'D'

    return 'C'
